"""Generate ``char_oxidation.yaml`` — a minimal gas + bulk-solid + surface
mechanism for the W5a FiniteSolidReactor tests (shrinking char particle).

Gas-species NASA-7 thermo is pulled verbatim from the installed ``gri30.yaml``
so the polynomials are guaranteed valid for the local Cantera; surface/bulk
species use constant-cp thermo (graphite-like values for C(b)).

Mechanism
---------
gas:      O2, CO, CO2, N2, one exothermic gas reaction  CO + 0.5 O2 => CO2
char:     C(b) bulk solid (fixed-stoichiometry, graphite density)
surface:  (s) empty site + O(s) adsorbed oxygen
    R1:  O2 + 2 (s) => 2 O(s)          (sticking-coefficient adsorption)
    R2:  O(s) + C(b) => CO + (s)       (oxidation, consumes bulk carbon)

Both surface reactions conserve sites and elements, so the reactor's
element-mass and site audits must hold to integrator tolerance.

Run:  python _make_char_fixture.py
"""
from __future__ import annotations

from pathlib import Path

import cantera as ct
import yaml

OUT = Path(__file__).parent / "char_oxidation.yaml"

GAS_SPECIES = ["O2", "CO", "CO2", "N2"]


def _gas_species_blocks() -> list:
    """Copy the NASA-7 blocks for the gas species out of gri30.yaml."""
    gri_path = None
    for d in ct.get_data_directories():
        cand = Path(d) / "gri30.yaml"
        if cand.is_file():
            gri_path = cand
            break
    if gri_path is None:  # pragma: no cover
        raise RuntimeError("gri30.yaml not found in the Cantera data path")
    with open(gri_path) as fh:
        gri = yaml.safe_load(fh)
    by_name = {s["name"]: s for s in gri["species"]}
    blocks = []
    for name in GAS_SPECIES:
        sp = dict(by_name[name])
        sp.pop("transport", None)          # not needed; keeps the fixture lean
        sp.pop("note", None)
        blocks.append(sp)
    return blocks


def build() -> dict:
    doc = {
        "description": (
            "Minimal char-oxidation mechanism (gas + bulk C(b) + surface) for "
            "FiniteSolidReactor tests. Generated by _make_char_fixture.py."
        ),
        "units": {"length": "cm", "quantity": "mol",
                  "activation-energy": "cal/mol"},
        "phases": [
            {
                "name": "gas",
                "thermo": "ideal-gas",
                "elements": ["O", "C", "N"],
                "species": GAS_SPECIES,
                "kinetics": "gas",
                "reactions": ["gas-reactions"],
                "state": {"T": 1400.0, "P": "1 atm",
                          "X": {"O2": 0.21, "N2": 0.79}},
            },
            {
                "name": "char",
                "thermo": "fixed-stoichiometry",
                "elements": ["C"],
                "species": ["C(b)"],
                "state": {"T": 1400.0, "P": "1 atm"},
            },
            {
                "name": "char_surface",
                "thermo": "ideal-surface",
                "elements": ["C", "O"],
                "species": ["(s)", "O(s)"],
                "kinetics": "surface",
                "reactions": ["surface-reactions"],
                "site-density": "2.72e-09 mol/cm^2",
                "adjacent-phases": ["gas", "char"],
                "state": {"T": 1400.0, "coverages": {"(s)": 1.0}},
            },
        ],
        "species": _gas_species_blocks() + [
            {
                "name": "C(b)",
                "composition": {"C": 1},
                "thermo": {
                    "model": "constant-cp",
                    "T0": 298.15,
                    "h0": "0.0 kJ/mol",
                    "s0": "5.74 J/mol/K",       # graphite standard entropy
                    "cp0": "8.53 J/mol/K",      # graphite cp(298)
                },
                "equation-of-state": {
                    "model": "constant-volume",
                    "density": "2.26 g/cm^3",   # graphite
                },
            },
            {
                "name": "(s)",
                "composition": {"C": 1},
                "thermo": {
                    "model": "constant-cp",
                    "T0": 298.15,
                    "h0": "0.0 kJ/mol",
                    "s0": "5.74 J/mol/K",
                    "cp0": "8.53 J/mol/K",
                },
            },
            {
                "name": "O(s)",
                "composition": {"C": 1, "O": 1},
                "thermo": {
                    "model": "constant-cp",
                    "T0": 298.15,
                    "h0": "-120.0 kJ/mol",      # chemisorbed O, plausible
                    "s0": "40.0 J/mol/K",
                    "cp0": "20.0 J/mol/K",
                },
            },
        ],
        "gas-reactions": [
            {
                "equation": "CO + 0.5 O2 => CO2",
                "rate-constant": {"A": 2.0e+12, "b": 0.0, "Ea": 40000.0},
                "orders": {"CO": 1.0, "O2": 0.5},
            },
        ],
        "surface-reactions": [
            {
                "equation": "O2 + 2 (s) => 2 O(s)",
                "sticking-coefficient": {"A": 0.05, "b": 0.0, "Ea": 0.0},
            },
            {
                "equation": "O(s) + C(b) => CO + (s)",
                "rate-constant": {"A": 1.0e+8, "b": 0.0, "Ea": 30000.0},
            },
        ],
    }
    return doc


def main() -> None:
    doc = build()
    with open(OUT, "w") as fh:
        yaml.dump(doc, fh, sort_keys=False, default_flow_style=None)
    # Verify it loads as a full gas+bulk+interface stack.
    gas = ct.Solution(str(OUT), "gas")
    bulk = ct.Solution(str(OUT), "char")
    surf = ct.Interface(str(OUT), "char_surface", [gas, bulk])
    surf.TP = 1400.0, ct.one_atm
    print(f"wrote {OUT}")
    print(f"  gas: {gas.n_species} species, {gas.n_reactions} reactions")
    print(f"  surface: {surf.n_species} species, {surf.n_reactions} reactions; "
          f"site density {surf.site_density} kmol/m^2")


if __name__ == "__main__":
    main()
